begin;
do $$
declare desk_id uuid:=gen_random_uuid(); cashier_id uuid:=gen_random_uuid(); game uuid:=gen_random_uuid(); cmd uuid:=gen_random_uuid(); request jsonb; result jsonb; rid uuid; v integer; before_jobs bigint; before_revision bigint;
begin
 select count(*) into before_jobs from reservation_private.outbox;
 select revision into before_revision from reservation_private.sheet_sync;
 insert into auth.users(id,email) values(desk_id,'test-desk-'||desk_id||'@example.invalid'),(cashier_id,'test-cashier-'||cashier_id||'@example.invalid');
 insert into user_profiles(user_id,role,active,display_name) values(desk_id,'desk',true,'TEST DESK'),(cashier_id,'cashier',true,'TEST CASHIER')
 on conflict(user_id) do update set role=excluded.role,active=true,display_name=excluded.display_name;
 update user_profiles set display_name='',username='TEST DESK' where user_id=desk_id;
 insert into reservation_games(id,title,starts_at,capacity,is_open,is_default_queue,is_test) values(game,'TEST SQL',now(),3,true,false,true);
 perform set_config('request.jwt.claim.sub',desk_id::text,true);
 request:=jsonb_build_object('game_id',game,'player_name_en','TEST ALPHA','arrival_at',now()+interval '30 minutes','party_size',2,'guest_note','TEST ONLY','source','desk');
 result:=submit_reservation_request(cmd,request); rid:=(result->>'reservation_id')::uuid;
 assert (select status='pending' and party_size=2 and is_test from reservations where id=rid),'desk submission remains pending';
 assert (select updated_actor='TEST DESK' from reservations where id=rid),'blank display name uses staff username';
 assert submit_reservation_request(cmd,request)=result,'response loss retry returns same booking';
 assert (select count(*)=1 from reservations where game_id=game),'idempotent creation';
 begin perform submit_reservation_request(cmd,request||'{"party_size":3}'); raise exception 'FAIL reused command'; exception when raise_exception then if sqlerrm<>'Request ID already used' then raise; end if; end;
 begin perform staff_reservation_command(gen_random_uuid(),rid,0,'approve'); raise exception 'FAIL desk approved'; exception when raise_exception then if sqlerrm<>'Cashier approval required' then raise; end if; end;
 perform set_config('request.jwt.claim.sub',cashier_id::text,true);
 cmd:=gen_random_uuid(); result:=staff_reservation_command(cmd,rid,0,'approve');
 assert result->>'status'='confirmed';
 assert staff_reservation_command(cmd,rid,0,'approve')=result,'lost approval response retry';
 begin update reservation_games set capacity=1 where id=game; raise exception 'FAIL reduced capacity below party size'; exception when raise_exception then if sqlerrm<>'Capacity cannot be lower than confirmed guests' then raise; end if; end;
 begin perform submit_reservation_request(gen_random_uuid(),request||'{"player_name_en":"  test   alpha  "}'); raise exception 'FAIL whitespace duplicate'; exception when raise_exception then if sqlerrm<>'An active reservation already exists for this player' then raise; end if; end;
 begin perform staff_reservation_command(gen_random_uuid(),rid,0,'cancel'); raise exception 'FAIL stale update'; exception when raise_exception then if sqlerrm<>'Reservation changed. Reload and try again' then raise; end if; end;
 result:=submit_reservation_request(gen_random_uuid(),request||'{"player_name_en":"TEST BETA"}');
 begin perform staff_reservation_command(gen_random_uuid(),(result->>'reservation_id')::uuid,0,'approve'); raise exception 'FAIL overbooked'; exception when raise_exception then if sqlerrm<>'Not enough seats available' then raise; end if; end;
 begin perform staff_reservation_command(gen_random_uuid(),(result->>'reservation_id')::uuid,0,'reject'); raise exception 'FAIL missing reason'; exception when raise_exception then if sqlerrm<>'Reason or alternative is required' then raise; end if; end;
 perform staff_reservation_command(gen_random_uuid(),(result->>'reservation_id')::uuid,0,'reject','{"reply":"Table full"}');
 assert (select status='rejected' and staff_reply='Table full' from reservations where id=(result->>'reservation_id')::uuid);
 perform set_config('request.jwt.claim.sub',desk_id::text,true);
 perform staff_reservation_command(gen_random_uuid(),rid,1,'request_change','{"party_size":3,"guest_note":"Add one guest"}');
 assert (select status='confirmed' and party_size=2 and request_kind='change' from reservations where id=rid),'old seat count retained before approval';
 perform set_config('request.jwt.claim.sub',cashier_id::text,true);
 perform staff_reservation_command(gen_random_uuid(),rid,2,'approve');
 assert (select status='confirmed' and party_size=3 and request_kind='none' from reservations where id=rid);
 perform set_config('request.jwt.claim.sub',desk_id::text,true);
 perform staff_reservation_command(gen_random_uuid(),rid,3,'request_cancel','{"reason":"Guest cannot come"}');
 assert (select status='confirmed' and request_kind='cancel' from reservations where id=rid);
 perform set_config('request.jwt.claim.sub',cashier_id::text,true);
 perform staff_reservation_command(gen_random_uuid(),rid,4,'approve');
 assert (select status='cancelled' and request_kind='none' from reservations where id=rid);
 assert (select count(*)>=5 from reservation_audit where reservation_id=rid and actor_name in ('TEST DESK','TEST CASHIER')),'actor history saved';
 assert (select count(*) from reservation_private.outbox)=before_jobs,'test creates no Telegram deliveries';
 assert (select revision from reservation_private.sheet_sync)=before_revision,'test creates no sheet exports';
 assert not has_function_privilege('anon','public.staff_reservation_command(uuid,uuid,integer,text,jsonb)','execute');
 assert not has_function_privilege('authenticated','public.claim_reservation_sheet(uuid)','execute');
 assert not has_function_privilege('authenticated','reservation_private.apply_operation(uuid,integer,text,jsonb,uuid,text)','execute');
 assert not has_table_privilege('authenticated','reservation_private.commands','select');
 perform set_config('request.jwt.claim.sub','',true);
 begin perform submit_reservation_request(gen_random_uuid(),request||'{"player_name_en":"TEST GUEST"}'); raise exception 'FAIL guest used test game'; exception when raise_exception then if sqlerrm<>'Staff login required' then raise; end if; end;
end $$;
rollback;
